The rule: each isolated pixel (a color that never appears adjacent to itself) is replaced by the majority color of its 4-neighbors (ignoring other noise pixels); ties go to the non-background color.

```python
def transform(grid):
    from collections import Counter
    R, C = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    def adjacent_self(color):
        for r in range(R):
            for c in range(C):
                if grid[r][c] == color:
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == color:
                            return True
        return False
    noise = {col for col in colors if not adjacent_self(col)}
    if not noise:
        return [row[:] for row in grid]
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] not in noise:
                continue
            counts = Counter()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r+dr, c+dc
                if 0 <= nr < R and 0 <= nc < C:
                    v = grid[nr][nc]
                    if v not in noise:
                        counts[v] += 1
            if not counts:
                out[r][c] = bg
                continue
            best = max(counts.values())
            tied = [v for v, n in counts.items() if n == best]
            if len(tied) == 1:
                out[r][c] = tied[0]
            else:
                nonbg = [v for v in tied if v != bg]
                pool = nonbg if nonbg else tied
                out[r][c] = max(pool, key=lambda v: (cnt[v], v))
    return out
